const panel=document.createElement('section');panel.className='live-mode';panel.innerHTML='<label for="conversation-mode">対話の方式</label><select id="conversation-mode"><option value="live">実AIサーバーを使う</option><option value="simulation">旧模擬対話を確認する</option></select><p id="live-status" role="status">サーバー状態を確認中。自動送信はしません。</p><label class="check-label"><input id="synthetic-input" type="checkbox">匿名の試験用入力のみ（実記録を含めない）</label>';
