async function api(route,body){const r=await fetch('/api/'+route,body===undefined?{credentials:'same-origin'}:{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-WHY-CSRF':csrf||''},body:JSON.stringify(body)});let x;try{x=await r.json()}catch{throw Error('server_response_invalid')}if(!r.ok){if(x.state){state=x.state;render()}throw Error(x.error||'request_failed')}return x}
