 const msgs=[...(state?.messages||[])];if(pendingPerson&&!msgs.some(m=>m.requestRef===pendingPerson.requestRef))msgs.push(pendingPerson);const log=$('live-log'),oldTop=log.scrollTop,nearBottom=log.scrollHeight-log.clientHeight-oldTop<60,key=msgs.map(m=>m.id+':'+m.status+':'+(m.delivery||'')).join('|'),changed=key!==renderedMessageKey,first=!renderedMessageKey,previousIds=new Set([...log.querySelectorAll('[data-message-id]')].map(el=>el.dataset.messageId)),arrived=msgs.some(m=>!previousIds.has(m.id));
