 $('live-hypotheses').innerHTML=(state?.hypotheses||[]).map(x=>'<div class="memory-row"><span class="meta">AI仮説 / '+(x.status==='withdrawn'?'本人が取下げ':x.status==='superseded'?'旧候補（後の応答で更新）':'未確認')+'</span><p>'+esc(x.label)+'</p><p class="quiet">根拠の引用：'+esc(x.evidenceQuote)+'</p>'+(x.status==='tentative'?'<button type="button" data-live-withdraw="'+x.id+'">この解釈は違う・取り下げる</button>':'')+'</div>').join('');
 const inactive=state&&state.status!=='active';$('chat-input').disabled=busy||!!inactive;$('send-chat').disabled=busy||!!inactive;document.querySelector('#home-form button[type=submit]').disabled=busy;
