async function boot(){try{state=await api('session');csrf=state.csrf;const bootText=(state.runtime.mode==='fixture'?'ローカルHTTP試験モード。実AIとは会話していません。':state.runtime.canSend?'サーバーの承認を確認。入力して、送信内容を確認できます。':'サーバー接続済み。実AI通信は承認待ち／停止中です。');$('live-status').textContent=bootText;if(state.runtime.mode==='fixture')note(bootText);render()}catch(e){note(window.WHYNative?'AI接続メニューで、このiPhoneの接続を確認してください。入力は送信していません。':'WHYサーバーに接続できません。START_WHY.cmd で起動してください。実AIの代わりに模擬応答は返しません。')}}
async function submit(text){if(busy||!text.trim())return;if(!csrf){await boot();if(!csrf)return}sendFailed=false;sendStatus('unsent');lastText=text.trim();location.hash='dialogue';$('chat-input').value=lastText;try{window.WHYCycle?.clearRawConsent();preview=await api('preview',{text:lastText,synthetic:$('synthetic-input').checked,sharedRecords:window.WHYCycle?.shared()||[],requestedStyle:window.WHYCycle?.style()||'auto'});$('live-preview-body').textContent=JSON.stringify(preview.body,null,2);$('live-consent-summary').textContent=preview.endpoint+' / '+preview.model+' / 1回の予約上限 US$'+preview.maximumAttemptCostUSD+' / '+(preview.runtime.mode==='fixture'?'ローカル試験・外部送信なし':'管理者承認と今回の同意がそろった範囲だけ送信');$('live-consent-error').textContent=preview.runtime.canSend?'':'現在は実通信停止中です。送信内容の確認だけできます。';$('live-consent-title').textContent='今回、外部AIへ送る内容';$('live-accept').hidden=false;$('live-refuse').textContent='送信しない・入力に戻る';$('live-accept').disabled=!preview.runtime.canSend;if(!preview.runtime.canSend)$('live-consent-error').textContent=errors[preview.runtime.stopReason]||'現在は送信できません。';dialog.showModal();$('live-refuse').focus()}catch(e){$('chat-input').value=lastText;note(errors[e.message]||e.message)}}
async function control(action){sendGeneration++;pendingPerson=null;sendStatus(['hold','end','revoke'].includes(action)?'stopped':$('chat-input').value.trim()?'unsent':'idle');try{state=await api('control',{action});if(dialog.open)dialog.close();preview=null;busy=false;render();note({end:'会話を終了しました。AI通信は行いません。',hold:'保留しました。AI通信は行いません。',resume:'会話を再開しました。',new:'新しい会話を開きました。',revoke:'送信同意を撤回し、応答待ちを中止しました。送信済みの外部情報は取り消せません。'}[action]);if(action==='new'||action==='resume')$('chat-input').focus()}catch(e){note(errors[e.message]||e.message)}}
$('live-accept').addEventListener('click',async()=>{if(!preview||busy)return;const p=preview,generation=++sendGeneration;pendingPerson={id:'pending-'+p.previewId,requestRef:p.previewId,role:'user',text:lastText,status:'current',source:'local-pending',delivery:'sending'};busy=true;sendStatus('sending');$('live-accept').disabled=true;$('live-consent-error').textContent='送信処理中…';try{await api('consent',{previewId:p.previewId,accept:true,retainRaw:window.WHYCycle?.rawConsent()===true});dialog.close();location.hash='dialogue';render();note('応答を待っています。保留・終了・同意撤回で中止できます。');const result=await api('send',{previewId:p.previewId});if(generation!==sendGeneration)return;pendingPerson=null;state=result;sendStatus('idle');$('chat-input').value='';$('home-input').value='';$('live-candidate').textContent=result.actionCandidate?'未採用の行動候補：'+result.actionCandidate+'。「試してみること」に自分で記入した場合だけ採用されます。':'';note(result.networkCalled?'実AIの応答を受信しました。':'ローカル試験応答を受信しました。実AIではありません。')}catch(e){if(generation!==sendGeneration)return;pendingPerson=null;sendStatus('failed');$('chat-input').value=lastText;$('live-consent-error').textContent=(errors[e.message]||e.message)+' 自動再送はしません。入力は残しています。';sendFailed=true;$('live-consent-title').textContent='送信できませんでした';$('live-accept').hidden=true;$('live-refuse').textContent='入力に戻る';if(!dialog.open)dialog.showModal();$('live-refuse').focus();note(errors[e.message]||e.message)}finally{if(generation===sendGeneration){busy=false;preview=null;$('live-accept').disabled=false;render();if(!dialog.open&&!$('chat-input').disabled)$('chat-input').focus()}}});
