$('live-export').addEventListener('click',async()=>{try{const x=await api('export',{});const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(x,null,2)],{type:'application/json'}));a.download='SUG-WHY-live-conversation.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);restoreText=JSON.stringify(x,null,2);note('会話を書き出しました。サーバー認証情報と送信同意は含みません。')}catch(e){note(e.message)}});
