window.addEventListener('why-sharing-changed',()=>{if(preview)control('revoke');});window.addEventListener('why-data-changed',()=>{if(preview)control('revoke');queueMicrotask(render)});window.addEventListener('hashchange',()=>{render();if(enabled&&location.hash==='#dialogue'&&!$('chat-input').disabled)$('chat-input').focus()});
window.WHYLive={reconnect:boot,get enabled(){return enabled},submit,control,current:()=>state?JSON.parse(JSON.stringify(state)):null,getAudit:()=>api('audit',{}),exportRaw:id=>api('audit-raw',{id,confirmExport:true}),revokeRaw:()=>api('raw-revoke',{}),report:async(messageId,reason)=>{state=await api('report',{messageId,reason});render()},deleteConversation:async()=>{state=await api('delete-conversation',{confirm:true});render()}};boot();
